import pathlib,subprocess,socket,time,re,json,secrets,os
assert os.getuid()!=0
policy=pathlib.Path('policy.conf').read_text()
# Candidate contains filters only; the fixture owns all protocols/listeners.
assert not re.search(r'\b(protocol|include|router|log|table)\b',policy,re.I),'only the two named filters may be submitted'
assert set(re.findall(r'\bfilter\s+(\w+)\s*\{',policy))=={'origin_only','admission'}
assert policy.count('{')==policy.count('}')
before=subprocess.check_output(['ip','-j','route','show','table','all'])
n=secrets.randbelow(160)+20
prefixes={'good':f'198.18.{n}.0/24','transit':f'198.18.{n+1}.0/24','origin':f'198.18.{n+2}.0/24','specific':f'198.18.{n+3}.0/25','unknown':f'198.19.{n}.0/24'}
ports=[];reserved=[]
for _ in range(2):
    s=socket.socket();s.bind(('127.0.0.1',0));ports.append(s.getsockname()[1]);reserved.append(s)
for s in reserved:s.close()
def receiver(maxlen):
    roa=''.join(f' route 198.18.{n+i}.0/24 max {maxlen if i==3 else 24} as 64496;\n' for i in range(4))
    return f"""
log stderr all; router id 192.0.2.2;
roa4 table r4;
ipv4 table accepted;
protocol static origins {{ roa4 {{ table r4; }}; {roa} }}
include "policy.conf";
protocol static igp {{ ipv4; route 192.0.2.254/32 blackhole; }}
protocol bgp upstream {{
 local 127.0.0.1 port {ports[1]} as 65002; neighbor 127.0.0.1 port {ports[0]} as 65001;
 multihop; passive on; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import all; export none; }};
}}
protocol pipe gate {{ table master4; peer table accepted; import none; export filter admission; }}
"""
static=''.join(f' route {p} blackhole;\n' for p in prefixes.values())
branches=''
for name,prefix in prefixes.items():
    path='bgp_path.prepend(64497);' if name=='origin' else 'bgp_path.prepend(64496);'
    if name=='transit':path+='bgp_path.prepend(65199);'
    branches+=f' if net = {prefix} then {{ {path} bgp_next_hop=192.0.2.254; accept; }}\n'
sender=f"""
log stderr all; router id 192.0.2.1;
protocol static seed {{ ipv4; {static} }}
protocol bgp peer {{
 local 127.0.0.1 port {ports[0]} as 65001; neighbor 127.0.0.1 port {ports[1]} as 65002;
 multihop; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import none; next hop keep; export filter {{ {branches} reject; }}; }};
}}
"""
pathlib.Path('sender.conf').write_text(sender);pathlib.Path('receiver.conf').write_text(receiver(24))
processes=[];handles=[]
def command(*args):
    result=subprocess.run(['birdc','-s','receiver.ctl',*args],capture_output=True,text=True,timeout=2)
    assert result.returncode==0,result.stdout+result.stderr
    return result.stdout
def routes(*args):
    text=command('show','route',*args,'all')
    return set(re.findall(r'(?m)^(\d+\.\d+\.\d+\.\d+/\d+)\s',text)),text
def wait_set(expected,*args):
    end=time.monotonic()+5;last=None
    while time.monotonic()<end:
        assert all(p.poll() is None for p in processes),[pathlib.Path(n+'.log').read_text() for n in ('sender','receiver')]
        last=routes(*args)
        if last[0]==expected:return last[1]
        time.sleep(.03)
    raise AssertionError({'expected':sorted(expected),'actual':last})
try:
    for name in ('receiver','sender'):
        checked=subprocess.run(['bird','-p','-c',name+'.conf'],capture_output=True,text=True,timeout=3)
        assert checked.returncode==0,checked.stderr
    for name in ('receiver','sender'):
        h=open(name+'.log','w');handles.append(h)
        processes.append(subprocess.Popen(['bird','-f','-c',name+'.conf','-s',name+'.ctl','-P',name+'.pid'],stdout=h,stderr=h))
    for _ in range(100):
        if all(pathlib.Path(n+'.ctl').exists() for n in ('sender','receiver')):break
        assert all(p.poll() is None for p in processes);time.sleep(.01)
    raw=wait_set(set(prefixes.values()),'table','master4','protocol','upstream')
    valid=wait_set({prefixes['good'],prefixes['transit']},'table','master4','filter','origin_only')
    admitted=wait_set({prefixes['good']},'table','accepted')
    assert 'BGP.as_path: 65001 65199 64496' in valid,'ROA-valid route with disallowed transit must remain visible in the origin-only audit'
    assert 'BGP.as_path: 65001 64497' in raw,'wrong-origin negative route must really be received'
    # ROA authority now permits /25; force the native pipe to reconsider existing routes.
    pathlib.Path('updated.conf').write_text(receiver(25))
    command('configure','"updated.conf"')
    command('reload','out','gate')
    updated_valid=wait_set({prefixes['good'],prefixes['transit'],prefixes['specific']},'table','master4','filter','origin_only')
    updated_admitted=wait_set({prefixes['good'],prefixes['specific']},'table','accepted')
    pathlib.Path('origin-admission-observations.json').write_text(json.dumps({'received':raw,'origin_valid':valid,'admitted':admitted,'after_maxlength_change':{'valid':updated_valid,'admitted':updated_admitted},'as_path_authentication':False,'public_rpki_chain_verified':False},indent=2))
finally:
    for p in processes:
        if p.poll() is None:p.terminate()
    for p in processes:
        try:p.wait(timeout=2)
        except subprocess.TimeoutExpired:p.kill();p.wait(timeout=2)
    for h in handles:h.close()
    assert before==subprocess.check_output(['ip','-j','route','show','table','all'])
